PART2 = [('finch2019', 'Poisson Clumping Heuristic', 'S2.3', 'derives M/M/c approximations from a clumping heuristic; our closed form is from the same family and is checked against the simulator, not against itself.'), ('chydzinski2024b', 'Response Time of Queueing Mechanisms', 'S2.3', 'computes response-time distributions for queueing mechanisms; we need only the mean wait, and we report where that mean misleads.'), ('zhu2026', 'Queues with Correlated Service Times', 'S2.3', 'allows correlated service times in a multi-server queue; our simulator draws independent service times, so that channel is out of scope.'), ('zuk2023', 'Partial Busy Period', 'S2.3', 'gives exact busy-period distributions for a multi-server queue; busy-period reasoning underlies the load we back out of a measured makespan.'), ('zuk2023b', 'Joint Queue-Length Distribution', 'S2.3', 'solves a non-preemptive multi-server queue explicitly; our workers are non-preemptive but our arrivals are generated endogenously by the agents.'), ('dauria2021', 'queueing-time dependent service rates', 'S2.3', 'lets service rates depend on queueing time; our instrument holds rates fixed and moves the offered load instead.'), ('schol2019', 'Large fork-join queues with nearly deterministic', 'S2.3', "characterises fork-join queues with near-deterministic arrivals; our pool is shared across one agent's own calls rather than per-job fork."), ('schol2023', 'Extreme values for the waiting time in large fork-join queues', 'S2.3', 'studies waiting-time extremes in fork-join queues; we study the wait of a call issued before it is needed.'), ('schol2022', 'Maximum waiting time in heavy-tailed fork-join queues', 'S2.3', 'derives maximum waiting times under heavy tails; our tail pair matches means, so tail shape enters without a mean shift.'), ('gocmen2025', 'Uncertain and Evolving Holding Costs', 'S2.3', 'schedules under evolving holding costs in a queue; our compensation cost is a fixed holding cost paid only on a miss.'), ('ji2024', 'Heavy traffic scaling limits for shortest remaining processing time', 'S2.3', 'gives heavy-traffic limits for SRPT queues; our instrument never reorders the queue and only changes when work is admitted.'), ('gao2026', 'Stability of Fork-Join Systems with Redundancy', 'S2.3', 'proves stability for fork-join systems with redundant servers; a redundant task is the closest queueing analogue of a speculative call.'), ('mohanty2024', 'Analysis of Fork-Join Scheduling on Heterogeneous Parallel Servers', 'S2.3', 'analyses fork-join scheduling on heterogeneous servers; our pool is homogeneous, which isolates width from placement.'), ('chydzinski2024c', 'A New Approximation for Multiserver Waiting Time', 'S2.3', 'approximates multiserver waiting times for layered networks; our closed form is a single-station approximation whose error we bound.'), ('zuk2023c', 'Explicit Results for the Distributions of Queue Lengths', 'S2.3', 'gives explicit queue-length distributions for a non-preemptive multi-server queue; we report a boundary rather than a distribution.'), ('pan2023', 'Refined mean', 'S2.3', 'refines mean-field approximation for queueing networks; a mean-field fixed point is what we test and find cannot express the flip.'), ('koroliouk2021', 'Diffusion Approximation of Queueing Systems', 'S2.3', 'approximates queueing systems by diffusion; we test our closed form against the simulator rather than against an approximation of it.'), ('barik2026', 'queueing model with heavy', 'S2.3', 'analyses an M^X/G/1 model with heavy arrivals; our arrivals are Poisson at a rate the agents generate, so batch structure is absent.'), ('whitt2000', 'M/GI/s', 'S2.4', 'shows heavy-tailed service times dominate multi-server waiting; our matched-mean pair tests that claim inside a simulated agent loop.'), ('sigman1999', 'A primer on heavy-tailed distributions', 'S2.4', 'explains when heavy tails matter in queues; we construct the pair so means match and only the shape moves.'), ('iyer2023', 'Microsecond-Scale Tail Latency', 'S2.4', 'reaches microsecond tail latency by approximate operations; we show the tail statistic is not what decides the speculation boundary.'), ('misra2019', 'Tail Latency in Datacenter-Scale File Systems', 'S2.4', 'manages tail latency in production file systems by scheduling; our intervention is admitting work early rather than reordering it.'), ('lawniczak2024', 'Proactive Rejection', 'S2.4', 'targets tail latency by proactively rejecting work in replicated systems; rejection and early admission are two ends of one trade in our model.'), ('kanev2014', 'power management and tail latency', 'S2.4', 'measures the tradeoff between power management and tail latency; the same trade shape appears between speculation width and pool contention.'), ('split2026', 'SymPathy for Large jobs Improves Tail latency', 'S2.4', 'improves tail latency by treating large jobs differently; our instrument classifies no jobs and still reproduces a boundary.'), ('aktas2017', 'Which Clones Should Attack and When', 'S2.4', 'decides which straggler clones to launch and when; we ask when launching anything early stops paying.'), ('aktas2017b', 'Straggler Mitigation by Delayed Relaunch', 'S2.4', 'delays relaunches to cut straggler tails; our speculation starts before a call is needed rather than after it is late.'), ('mackenzie2020', 'Managing tail latency in large scale information retrieval', 'S2.4', 'manages tail latency in large-scale retrieval systems; we measure a tail change that the mean does not show.'), ('chen2009', 'distribution on network traffic', 'S2.4', 'relates heavy-tailed distributions to network traffic behaviour; our tail pair is generated, so no network measurement is assumed.'), ('mehan2026', 'Retry Amplification', 'S2.5', 'analyses how retries amplify load in distributed systems; a discarded speculative call is a retry nobody requested.'), ('dusad2025', 'Taming Asynchrony in Distributed Payment Systems', 'S2.5', 'states the idempotency guarantees payment systems need; our non-idempotent fraction is the probability a discarded call cannot be undone.'), ('lai2024', 'Reliable Event-Driven Processing', 'S2.5', 'makes event processing reliable with stage-aware retries; we charge compensation as worker-busy time rather than as a correctness loss.'), ('konasani2026', 'Duplicate Trade Detection and Idempotency', 'S2.5', 'detects duplicate trades and enforces idempotency; our instrument assumes compensation succeeds and prices only its contention.'), ('bush2022', 'Stable Scheduling in Transactional Memory', 'S2.5', 'schedules transactional memory to remain stable; an aborted transaction pays the same kind of loss as our non-idempotent miss.'), ('progressive1993', 'Progressive Retry', 'S2.5', 'retries software recovery progressively after a failure; we measure the pool cost of redoing work that was started speculatively.'), ('tmretry2008', 'Transactional memory retry mechanisms', 'S2.5', 'compares retry mechanisms for transactional memory; that retry policy is local, while ours competes for a shared pool.'), ('fagin2024', 'Minimal idempotency', 'S2.5', 'formalises minimal and partial idempotency; our q is the partial-idempotency case in which a repeat is not free.'), ('kim2024svc', 'Idempotency Mechanisms in Digital Payment Systems', 'S2.5', 'documents idempotency keys as the industry answer to duplicate requests; our speculative miss duplicates work no key can suppress.'), ('intro1998', 'An introduction to idempotency', 'S2.5', 'introduces idempotency as an algebraic property; we use it as a workload parameter, the probability an effect can be repeated.')]
